messages.content:
Game "Relik Candi" siap dibangun sebagai Endless Runner arcade retro pixel dengan rintangan batu runtuh dan genangan berlumut. Saya memakai pengaturan Normal (speed 360, 3 nyawa) dan koin skor generik tanpa konten belajar.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "relik-candi", title: "Relik Candi", seed: "relik-candi-01",
  theme: { preset: "retro-pixel" },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu-runtuh", w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "genangan",    w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: false },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```
